<?php
use App\Core\Db; require_once __DIR__.'/_common.php';
$pdo=Db::pdo(); $u=\App\Core\Auth::user(); $uid=approval_current_employee_id($pdo,$u); $userEmail=approval_current_user_email($u); $userName=approval_current_user_name($u); $showCancelled=(isset($_GET['show_cancelled']) && (string)$_GET['show_cancelled']==='1'); $rows=array();
if($pdo){$st=$pdo->prepare("SELECT d.*,l.role_type current_role,my.line_status my_line_status FROM cpms_approval_documents d LEFT JOIN cpms_approval_lines l ON l.document_id=d.id AND l.line_status='PENDING' LEFT JOIN cpms_approval_lines my ON my.document_id=d.id AND (my.approver_id=:uid OR my.approver_email=:email) WHERE (:show_cancelled=1 OR d.doc_status <> 'CANCELLED') AND (d.created_by_id=:uid OR d.created_by_name=:uname OR EXISTS (SELECT 1 FROM cpms_approval_lines x WHERE x.document_id=d.id AND (x.approver_id=:uid OR x.approver_email=:email))) ORDER BY d.id DESC LIMIT 200");$st->execute(array(':uid'=>$uid,':email'=>$userEmail,':uname'=>$userName,':show_cancelled'=>$showCancelled?1:0));$rows=$st->fetchAll();}
$cnt=array('recv'=>0,'mine'=>0,'prog'=>0,'rej'=>0); foreach($rows as $r){ $isMine=false; if($uid>0&&(int)$r['created_by_id']===$uid)$isMine=true; if(!$isMine&&$userName!==''&&trim((string)$r['created_by_name'])===$userName)$isMine=true; if($isMine)$cnt['mine']++; if(isset($r['my_line_status'])&&$r['my_line_status']!==null&&trim((string)$r['my_line_status'])!=='')$cnt['recv']++; $status=strtoupper($r['doc_status']); if($status==='PENDING')$cnt['prog']++; if($status==='REJECTED')$cnt['rej']++; }
$canDb=\App\Core\Auth::isMaster()||\App\Core\Auth::canManageEmployees()||\App\Core\Auth::userRole()==='executive';
?><div class="space-y-5"><div class="bg-gradient-to-r from-indigo-600 to-cyan-500 rounded-3xl p-7 text-white shadow-xl"><div class="flex justify-between"><div><h2 class="text-3xl font-extrabold">전자결재</h2><p class="mt-2 text-indigo-100">기안서와 휴가계를 작성하고 결재 진행상태를 확인합니다.</p><?php if($canDb){ ?><p class="mt-2 text-indigo-100 text-sm">전자결재 DB 설치/확인은 문서/결재라인/첨부/알림 테이블을 생성합니다. 직원별 역할/생년월일/Google Chat 정보는 관리 &gt; 직원명부에서 생성/설정합니다.</p><?php } ?></div><div class="space-x-2"><?php if($canDb){ ?><a class="px-4 py-2 rounded-xl bg-amber-200 text-amber-900" href="?r=db_setup_approval">전자결재 DB 설치/확인</a><?php } ?><a class="px-4 py-2 rounded-xl bg-white text-indigo-700" href="?r=approval_create&type=proposal">기안서 작성</a><a class="px-4 py-2 rounded-xl bg-white/20" href="?r=approval_create&type=leave">휴가계 작성</a></div><div class="mt-3"><?php if(!$showCancelled){ ?><a class="underline text-indigo-100" href="?r=approval_home&show_cancelled=1">취소문서 보기</a><?php } else { ?><a class="underline text-indigo-100" href="?r=approval_home">취소문서 숨기기</a><?php } ?></div></div>
<div class="grid grid-cols-2 md:grid-cols-4 gap-3"><?php $cards=array('받은 결재'=>'recv','나의 요청'=>'mine','진행중'=>'prog','반려'=>'rej'); foreach($cards as $k=>$v){?><div class="bg-white rounded-2xl border p-4"><div class="text-gray-500"><?php echo h($k);?></div><div class="text-2xl font-extrabold"><?php echo (int)$cnt[$v];?></div></div><?php }?></div>
<div class="bg-white rounded-3xl border p-5 overflow-x-auto"><table class="w-full text-xl"><tr class="text-left border-b"><th class="py-3">종류</th><th class="py-3">제목</th><th class="py-3">작성자</th><th class="py-3">상태</th><th class="py-3">현재 단계</th><th class="py-3">작성일시</th><th class="py-3">액션</th></tr><?php foreach($rows as $r){?><tr class="border-b"><td class="py-3"><?php echo h(approval_doc_label($r['doc_type']));?></td><td class="py-3"><?php echo h($r['title']);?></td><td class="py-3"><?php echo h($r['created_by_name']);?></td><td class="py-3"><span class="px-4 py-2 text-lg rounded-full border <?php echo approval_status_badge($r['doc_status']);?>"><?php echo h(approval_status_label($r['doc_status']));?></span></td><td class="py-3"><?php echo h($r['current_role']?$r['current_role']:'-');?></td><td class="py-3"><?php echo h($r['created_at']);?></td><td class="py-3"><div class="flex flex-wrap items-center gap-3"><a href="?r=approval_detail&id=<?php echo (int)$r['id'];?>" class="text-indigo-600 font-semibold">상세보기</a><?php $rowMine=false; if($uid>0&&(int)$r['created_by_id']===$uid)$rowMine=true; if(!$rowMine&&$userName!==''&&trim((string)$r['created_by_name'])===$userName)$rowMine=true; if($rowMine&&in_array($r['doc_status'],array('PENDING','DRAFT'))){?><form method="post" action="?r=approval_cancel" style="display:inline;"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="text-rose-600 font-semibold">요청취소</button></form><?php } if($rowMine&&$r['doc_status']==='CANCELLED'){?><form method="post" action="?r=approval_delete" style="display:inline;"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="text-gray-700 font-semibold" onclick="return confirm('취소 문서를 삭제하시겠습니까?');">삭제</button></form><?php } ?></div></td></tr><?php } ?></table></div></div>